from collections import defaultdict
sanctioned={'drive.google.com','slack.com','notion.so'}
logs=[('kim','drive.google.com',30),('lee','wetransfer.com',850),('park','wetransfer.com',120),
      ('kim','slack.com',2),('choi','pastebin.com',1),('lee','notion.so',5),('jung','wetransfer.com',40)]
users=defaultdict(set); up=defaultdict(int)
for u,d,mb in logs:
    if d not in sanctioned: users[d].add(u); up[d]+=mb
for d in sorted(users,key=lambda d:-up[d]): print(d,len(users[d]),'명',up[d],'MB')

import statistics as st
dl={'kim':[12,9,15,11,10,13,240],'lee':[3,5,4,2,6,4,5]}
for u,xs in dl.items():
    base=xs[:-1]; med=st.median(base); mad=st.median(abs(x-med) for x in base) or 1
    z=(xs[-1]-med)/(1.4826*mad); print(u,'오늘',xs[-1],'평소',med,'점수',round(z,1),'경보' if z>5 else '정상')
